    \"guide\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19 || >=24\"\n  },\n  \"scripts\": {\n    \"clean\": \"node scripts/clean-lib.mjs\",\n    \"build:dsh-std\": \"pnpm --dir vendor/dsh-std install --frozen-lockfile --ignore-scripts && pnpm --dir vendor/dsh-std --filter @dsh-std/core --filter @dsh-std/manifest --filter @dsh-std/connection --filter @dsh-std/presentation --filter @dsh-std/command --filter @dsh-std/storage --filter @dsh-std/messages -r build\",\n    \"build:mathjax\": \"pnpm --filter @dsh-tui-vendor/mathjax-tex-svg run build\",\n    \"build:vendor\": \"node scripts/build-vendor.mjs\",\n    \"compile\": \"node scripts/build-vendor.mjs && npm run clean && node --import tsx/esm scripts/gen-backend-index.mjs && tsc -p tsconfig.json && node scripts/gen-settings-json.mjs && node scripts/copy-notify-helper.mjs\",\n    \"compile:src\": \"node --import tsx/esm scripts/gen-backend-index.mjs && tsc -p tsconfig.json && node scripts/gen-settings-json.mjs && node scripts/copy-notify-helper.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.typecheck.json\",\n    \"prepare\": \"node scripts/prepare-guard.mjs && npm run compile\",\n    \"build\": \"npm run compile && npm run verify:build\",\n    \"dev\": \"node scripts/dev-test.mjs\",\n    \"dev:copy-config\": \"node scripts/dev-copy-config.mjs\",\n    \"dev:test\": \"node scripts/verify-dev-command.mjs && node scripts/dev-test.mjs --no-launch\",\n    \"prompt:debug\": \"node scripts/read-prompt-debug.mjs\",\n    \"tui\": \"node --import tsx/esm scripts/run.ts\",\n    \"smoke\": \"node --import tsx/esm scripts/smoke.tsx\",\n    \"verify:build\": \"node scripts/run-verify-build.mjs\",\n    \"verify:cli\": \"node --test cli/test/cli.test.mjs cli/test/edges.test.mjs cli/test/package.test.mjs cli/test/boundary.test.mjs\",\n    \"verify:cli:runtime\": \"node cli/test/runtime.mjs\",\n    \"verify:cli-subcommands\": \"node scripts/verify-cli-subcommands.mjs\",\n    \"verify:boundary\": \"node --import tsx/esm scripts/verify-