lpha.4 || 0.1.2-alpha.5 || 0.1.2-rc.1 || 0.1.3-alpha.2 || 0.1.5-alpha.1 || 0.1.5-alpha.2 || 0.1.5-rc.1 || 0.1.7-rc.1 || 0.1.7-rc.2 || 0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-user-approval\": \"^0.1.0-rc.6 || ^0.1.1-rc.1 || 0.1.2-alpha.3 || 0.1.2-alpha.4 || 0.1.2-alpha.5 || 0.1.2-rc.1 || 0.1.3-alpha.2 || 0.1.5-alpha.1 || 0.1.5-alpha.2 || 0.1.5-rc.1 || 0.1.7-rc.1 || 0.1.7-rc.2 || 0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-user-questions\": \"^0.1.0-rc.6 || ^0.1.1-rc.1 || 0.1.2-alpha.3 || 0.1.2-alpha.4 || 0.1.2-alpha.5 || 0.1.2-rc.1 || 0.1.3-alpha.2 || 0.1.5-alpha.1 || 0.1.5-alpha.2 || 0.1.5-rc.1 || 0.1.7-rc.1 || 0.1.7-rc.2 || 0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-web\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-web-app\": \"^0.1.0-rc.6 || ^0.1.1-rc.1 || 0.1.2-alpha.3 || 0.1.2-alpha.4 || 0.1.2-alpha.5 || 0.1.2-rc.1 || 0.1.3-alpha.2 || 0.1.5-alpha.1 || 0.1.5-alpha.2 || 0.1.5-rc.1 || 0.1.7-rc.1 || 0.1.7-rc.2 || 0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-web-deepseek-api\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-workflow-ptc\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-workspace\": \"^0.1.0-rc.6 || ^0.1.1-rc.1 || 0.1.2-alpha.3 || 0.1.2-alpha.4 || 0.1.2-alpha.5 || 0.1.2-rc.1 || 0.1.3-alpha.2 || 0.1.5-alpha.1 || 0.1.5-alpha.2 || 0.1.5-rc.1 || 0.1.7-rc.1 || 0.1.7-rc.2 || 0.2.0-rc.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3 || 0.2.1-rc.4 || 0.2.1-rc.5 || 0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1 || 3.18.5-alpha.2\",\n    \"@types/lodash-es\": \"^4.17.0\",\n    \"@types/node\": \"^26.4.0\",\n    \"@types/react\": \"^19.0.0\",\n    \"@types/react-reconciler\": \"^0.33.0\",\n    \"@types/semver\": \"^7.0.0\",\n    \"@types/ws\": \"^8.18.2\",\n    \"@xterm/headless\": \"^6.0.0\",\n    \"tar\": \"^7.5.22\",\n    \"tsx\": \"^4.0.0\",\n    \"typescript\": \"^6.0.3\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"icon\": \"./assets/plugin-icon.svg\"\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# The dsh-tui bundle patch: the interactive terminal front door over the\n# dsh-base layer. Applied after dsh-base's insert; rows here override base\n# rows by id, with the profile's own cordis.patch.yml and any --patch\n# overlays still to come.\n#\n# A patch replaces the targeted row's whole `config`, so each row below\n# restates every key it owns (see the dsh-base patch for the shared\n# defaults). The dsh-base core rows that need no dsh-tui value — tools,\n# sandbox/approval policy, skills, goal, plan mode, workspace context,\n# telemetry — are inherited unchanged.\n\n# ── surface-specific values over the dsh-base layer ─────────────────────────\n\n# The dsh-tui deployment persona; DSH_TUI_PERSONA overrides the coding-agent\n# default (the base persona is empty). dsh-system-prompt renamed the slot at\n# 0.1.3-alpha.2 (`persona` → `personaPrefix`, with an optional suffix\n# counterpart); older cohorts only accept `persona`, so the key follows the\n# installed package version.\n- id: system-prompt\n  config: !!js >-\n    (() => {\n      const persona = process.env.DSH_TUI_PERSONA ?? 'You are a coding agent.'\n      try {\n        const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n        const fs = process.getBuiltinModule('node:fs')\n        const manifest = require.resolve('@deepseek-ai/dsh-system-prompt/package.json')\n        const version = String(JSON.parse(fs.readFileSync(manifest, 'utf8')).version ?? '')\n        const match = /^(\\d+)\\.(\\d+)\\.(\\d+)/u.exec(version)\n        const [major, minor, patch] = match === null ? [0, 0, 0] : [Number(match[1]), Number(match[2]), Number(match[3])]\n        if (major > 0 || minor > 1 || (minor === 1 && patch >= 3)) return { personaPrefix: persona }\n        return { persona }\n      } catch {\n        return { personaPrefix: persona }\n      }\n    })()\n\n# The native DeepSeek adapter, pinned to the harness defaults: full thinking\n# at max effort, key and base URL from the launching environment. The base\n# entry supplies the adapter defaults; /settings edits the profile config\n# on 0.1.7 (older hosts apply their separate settings document per request).\n# rc.6 schema key is `apiKeyEnv` (credential-ref env var NAME, default\n# DEEPSEEK_API_KEY); the old snapshot's `apiKey` key no longer exists.\n- id: llm-deepseek\n  config:\n    apiKeyEnv: 'DEEPSEEK_API_KEY'\n    baseURL: !!js process.env.DEEPSEEK_BASE_URL\n    thinking: enabled\n    reasoningEffort: max\n\n# The TUI creates (or resumes) its agent at runtime through the agent\n# factory; no declarative agents are started at boot, and the configured\n# agent list stays the base's empty default.\n- id: agent-loop\n  config:\n    agents: []\n\n# ── agent presets (issue #8) ────────────────────────────────────────────────\n#\n# The model-facing plugin set moves INTO the preset registry: every\n# session composes its tools/prompt sections from one preset\n# (standard/ptc/minimal/cordis) instead of the host rows below. The TUI's\n# roster row uses the scoped `dsh-tui-agent-presets` id. The 0.1.2 generation\n# prepends its bundled system root; legacy 0.1.1-rc.2 still needs the dsh CLI's\n# `config/agent-presets/` directory supplied explicitly. Both append\n# `$DSH_HOME/.agent-presets`. Mirroring the official dsh-web-app patch: every\n# dsh-base row a preset now owns is disabled here, so a minimal agent does not\n# leak host-layer tools (an agent's registry view resolves agent → preset →\n# global). On 0.1.7, the adapter registers official declarative bundles;\n# directory discovery and the old code-runtime host row stay disabled.\n\n- id: agent-instructions\n  disabled: true\n\n- id: command-compact\n  disabled: true\n\n# compaction lives in the preset's own isolate realm (standard/ptc/cordis\n# carry `compaction-basic` with package defaults; minimal has none). The old\n# ratio/retain tunables retired with this host row — preset compositions own\n# their compaction config.\n- id: compaction-basic\n  disabled: true\n\n- id: plan-mode\n  disabled: true\n\n- id: skill-filesystem\n  disabled: true\n\n- id: tool-bash\n  disabled: true\n\n- id: tool-fs\n  disabled: true\n\n- id: tool-fs-search\n  disabled: true\n\n- id: command-goal\n  # rc.2 presets do not carry this command, so their host row must remain\n  # active. Newer packages disable it only when the shipped standard preset\n  # really owns the command; reading the capability avoids guessing from\n  # another optional Loader row.\n  disabled: !!js >-\n    (() => {\n      const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n      const fs = process.getBuiltinModule('node:fs')\n      const path = process.getBuiltinModule('node:path')\n      try {\n        require.resolve('@deepseek-ai/dsh-agent-preset-registry/package.json')\n        return true\n      } catch {}\n      try {\n        const manifest = require.resolve('@deepseek-ai/dsh-agent-presets/package.json')\n        const preset = path.join(path.dirname(manifest), 'presets', 'standard', 'agent.cordis.yml')\n        return fs.readFileSync(preset, 'utf8')\n          .split(/\\r?\\n/u)\n          .some(line => line.trim() === '- id: command-goal')\n      } catch {\n        return false\n      }\n    })()\n\n- id: tool-goal\n  disabled: true\n\n- id: tool-jobs\n  disabled: true\n\n- id: tool-pwsh\n  disabled: true\n\n- id: tool-ralph\n  disabled: true\n\n- id: tool-result-pruner\n  disabled: true\n\n- id: tool-skill\n  disabled: true\n\n# `tool-str-replace-editor` carries no disable row: dsh-base registered that\n# entry only up to the 0.1.2 line, and from 0.1.3-alpha.2 it is opt-in (see the\n# dsh-base README). A row here would target a missing id and log\n# `patch: entry \"tool-str-replace-editor\" not found` on every 0.1.3+ boot.\n# Presets that expose the tool re-add the entry themselves.\n\n# Delegation tools (subagent spawn/fork, controls, workflows) are preset rows\n# now; the preset's `delegation` group re-adds them with package defaults, so\n# the former TUI's depth-1 cap no longer applies.\n- id: tool-subagent\n  disabled: true\n\n- id: tool-subagent-control\n  disabled: true\n\n- id: tool-subagent-fork\n  disabled: true\n\n- id: tool-subagent-list-agents\n  disabled: true\n\n- id: tool-todo\n  disabled: true\n\n- id: tool-web\n  disabled: true\n\n- id: tool-workflow\n  disabled: true\n\n# Windows has no sandbox confinement backend yet (sandbox-local's win32\n# chain is empty); use danger-full-access on Windows so bash commands can\n# run. Other platforms keep the base workspace-write default. DSH_PERMISSION_MODE\n# is the INITIAL state of a launch — the remembered /permission pick\n# (~/.dsh-tui/permission.json) outranks it whenever it is not set.\n- id: sandbox-policy\n  config:\n    mode: !!js \"process.platform === 'win32' ? 'danger-full-access' : (process.env.DSH_PERMISSION_MODE ?? 'workspace-write')\"\n    workspaceRoot: !!js process.cwd()\n\n# On Windows, skip approval prompts (no sandbox = the user's terminal trust\n# model, matching every other terminal coding agent).\n- id: approval\n  config:\n    policy: !!js \"process.platform === 'win32' ? 'never' : ((process.env.DSH_PERMISSION_MODE ?? 'workspace-write') === 'danger-full-access' ? 'never' : 'ask')\"\n\n# Sessions live in the shared JSONL store (~/.dsh/sessions) — the same\n# backend dsh web writes — so /resume here and the web session list see each\n# other (#24). The row itself comes from the dsh-base layer; this override\n# only re-points the root when DSH_TUI_SESSION_ROOT is set (test isolation).\n- id: session-persistence-jsonl\n  config:\n    root: !!js process.env.DSH_TUI_SESSION_ROOT ?? dshHomePath('sessions')\n\n# ── dsh-tui rows ────────────────────────────────────────────────────────────\n\n# The `user-interaction` service row comes from the dsh-base bundle layer\n# (mounted before this layer); do not insert it again — the include patch\n# semantics would create a duplicate row. dsh-tui defensively creates the\n# service on its own context when no composition provides it (bare\n# `dsh --config cordis.yml` boots), then mounts the model-facing\n# ask_user_question tool. On legacy hosts it registers the TUI provider on\n# `ctx.userQuestions`; on Alpha it answers the scoped\n# `user-questions/request` waterfall.\n\n- insert:\n    # Workspace grouping is a separate durable ledger, not a cwd-derived\n    # projection. Mount the same domain stack and storage root as dsh-web-app\n    # so TUI-created sessions can attach to the exact registry Web reads.\n    #\n    # These rows own host-plane services that the official web-app bundle may\n    # already mount. Loader entry ids are process-global, so these\n    # rows use dsh-tui-* scoped ids and self-disable when an enabled row with\n    # the official id/name is already present in the tree. The disabled check\n    # is evaluated during the same include update that inserts every row, so\n    # it sees the web-app rows regardless of their activation state.\n    - id: dsh-tui-storage\n      name: '@deepseek-ai/dsh-storage'\n      disabled: !!js \"[...ctx.loader.entries()].some(entry => entry.options.id === 'storage' && entry.options.name === '@deepseek-ai/dsh-storage' && !entry.disabled)\"\n\n    - id: dsh-tui-storage-json\n      name: '@deepseek-ai/dsh-storage-json'\n      disabled: !!js \"[...ctx.loader.entries()].some(entry => entry.options.id === 'storage-json' && entry.options.name === '@deepseek-ai/dsh-storage-json' && !entry.disabled)\"\n      config:\n        root: !!js dshHomePath('storages')\n\n    - id: dsh-tui-storage-domain\n      name: '@deepseek-ai/dsh-storage-domain'\n      disabled: !!js \"[...ctx.loader.entries()].some(entry => entry.options.id === 'storage-domain' && entry.options.name === '@deepseek-ai/dsh-storage-domain' && !entry.disabled)\"\n      config:\n        backend: json\n\n    # Alpha moved the durable storage stack into dsh-base, so these three\n    # scoped copies self-disable there. Keep them for the validated rc lines,\n    # whose base layer does not provide the stack to a TUI-only profile.\n\n    - id: dsh-tui-workspace\n      name: '@deepseek-ai/dsh-workspace'\n      disabled: !!js \"[...ctx.loader.entries()].some(entry => entry.options.id === 'workspace' && entry.options.name === '@deepseek-ai/dsh-workspace' && !entry.disabled)\"\n\n    # PTC presentation waits on this Host service. The scoped row supports a\n    # TUI-only profile and yields to the official web-app row in mixed profiles.\n    - id: dsh-tui-code-runtime\n      name: '@deepseek-ai/dsh-code-runtime-worker-thread'\n      disabled: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          try { require.resolve('@deepseek-ai/dsh-ptc-runtime-node/package.json'); return true } catch {}\n          return [...ctx.loader.entries()].some(entry => entry.options.id === 'code-runtime' && entry.options.name === '@deepseek-ai/dsh-code-runtime-worker-thread' && !entry.disabled)\n        })()\n\n    # 0.1.2 presets opt their delegation tool into Host-owned model-selection\n    # settings. Without this service standard/ptc/cordis preset mounting fails.\n    # The package subpath does not exist on rc.2, so resolve that capability\n    # directly before Loader attempts the import. An enabled official row still\n    # owns the seat in mixed profiles.\n    - id: dsh-tui-subagent-model-selection-settings\n      name: '@deepseek-ai/dsh-tool-subagent/model-selection-settings'\n      disabled: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          try {\n            require.resolve('@deepseek-ai/dsh-tool-subagent/model-selection-settings')\n          } catch {\n            return true\n          }\n          return [...ctx.loader.entries()].some(entry => entry.options.id === 'subagent-model-selection-settings' && entry.options.name === '@deepseek-ai/dsh-tool-subagent/model-selection-settings' && !entry.disabled)\n        })()\n\n    # Generic terminal workspace registry. Optional plugins add providers;\n    # the TUI itself always supplies LOCAL and has no provider-specific code.\n    - id: dsh-tui-workspaces\n      name: '@deepseek-harness-tui/dsh-tui/workspaces'\n\n    # Optional plugins contribute nested slash-command completion here;\n    # execution and durable command events remain owned by dsh-commands.\n    - id: dsh-tui-command-trees\n      name: '@deepseek-harness-tui/dsh-tui/command-trees'\n    # Optional plugins declare editable settings sections here (issue #165);\n    # storage, validation and writes remain owned by the dsh settings service.\n    - id: dsh-tui-settings-sections\n      name: '@deepseek-harness-tui/dsh-tui/settings-sections'\n\n    # Optional plugins register full-screen scenes (trajectory-style whole-\n    # terminal views) here and open them from their own command handlers;\n    # rendering and input ownership remain owned by the TUI's Chat screen.\n    - id: dsh-tui-scenes\n      name: '@deepseek-harness-tui/dsh-tui/scenes'\n\n    # Optional plugins register side-panel surfaces (sidebar Panel +\n    # compact row, experimental §18) here; admission, budgets and crash\n    # isolation remain owned by the tuiPanels runtime + PanelStore.\n    - id: dsh-tui-panels\n      name: '@deepseek-harness-tui/dsh-tui/panels'\n\n    # Plugin-interop anchor (Community Consensus v0.15): the unified grant\n    # store, runtime generation id, and Host Descriptor live here; later\n    # contract surfaces (plugin storage, message observation, effect\n    # ledger) mount off THIS row's apply, so the patch surface changes only\n    # once for the whole alignment. Mounted ahead of the extensions row and\n    # any third-party plugin row.\n    - id: dsh-tui-plugin-host\n      name: '@deepseek-harness-tui/dsh-tui/plugin-host'\n\n    # Plugin-facing UI seams (the pi-style extension surface): managed\n    # dialogs (select/confirm/input), keyed status-line contributions,\n    # keyboard shortcuts, and custom session-entry text renderers. The\n    # decision events (tui/input, tui/rewind-prompt, tui/session-switch,\n    # tui/compact, …) are fired by the channel on the cordis bus directly\n    # and need no row.\n    - id: dsh-tui-extensions\n      name: '@deepseek-harness-tui/dsh-tui/extensions'\n\n    # The agent-preset roster (issue #8): `ctx.agentPresets`, the service the\n    # TUI composes every session's model-facing world from. 0.1.2 packages\n    # prepend their bundled presets as the read-only system root; legacy rc.2\n    # packages have no bundled root and still scan the dsh CLI directory. Both append\n    # `$DSH_HOME/.agent-presets` as the user root. Deployment-added roots may\n    # still be supplied by a later patch.\n    - id: dsh-tui-agent-presets\n      name: '@deepseek-ai/dsh-agent-presets'\n      disabled: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          try { require.resolve('@deepseek-ai/dsh-agent-preset-registry/package.json'); return true } catch {}\n          return [...ctx.loader.entries()].some(entry => entry.options.id === 'agent-presets' && entry.options.name === '@deepseek-ai/dsh-agent-presets' && !entry.disabled)\n        })()\n      config: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          const fs = process.getBuiltinModule('node:fs')\n          const path = process.getBuiltinModule('node:path')\n          try {\n            const manifest = require.resolve('@deepseek-ai/dsh-agent-presets/package.json')\n            if (fs.existsSync(path.join(path.dirname(manifest), 'presets'))) {\n              return { default: 'standard' }\n            }\n          } catch {\n            // Let the roster import report a missing package; preserve the rc\n            // root fallback below for every package generation without one.\n          }\n          const base = ctx.baseUrl\n          if (!base) return { default: 'standard' }\n          const root = new URL('../node_modules/@deepseek-ai/dsh/config/agent-presets/', base)\n          let rootPath = decodeURIComponent(root.pathname)\n          if (/^\\/[A-Za-z]:/.test(rootPath)) rootPath = rootPath.slice(1)\n          return { default: 'standard', roots: [{ path: rootPath, trust: 'system' }] }\n        })()\n\n    # 0.1.7 replaces directory discovery with declarations in a registry.\n    # The TUI registers the official bundle defaults only when Web has not\n    # already declared them. PTC's host runtime now comes from dsh-base.\n    - id: dsh-tui-agent-preset-registry\n      name: '@deepseek-ai/dsh-agent-preset-registry'\n      disabled: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          try { require.resolve('@deepseek-ai/dsh-agent-preset-registry/package.json') } catch { return true }\n          return [...ctx.loader.entries()].some(entry => entry.options.id === 'agent-preset-registry' && entry.options.name === '@deepseek-ai/dsh-agent-preset-registry' && !entry.disabled)\n        })()\n      config:\n        default: standard\n\n    # Host-plane services the `cordis` preset's plugin-experimentation tool\n    # waits on (dynamicCordisRunner/cordisInspect); dsh-base carries no such\n    # row — the official web app inserts it the same way, so this copy yields\n    # to it when it is already present.\n    - id: dsh-tui-cordis-host-runner\n      name: '@deepseek-ai/dsh-cordis-host-runner'\n      disabled: !!js \"[...ctx.loader.entries()].some(entry => entry.options.id === 'cordis-host-runner' && entry.options.name === '@deepseek-ai/dsh-cordis-host-runner' && !entry.disabled)\"\n\n    # DeepSeek account sign-in uses the Host-owned /oauth/callback route. A\n    # TUI-only profile needs a loopback listener; a mixed Web+TUI profile\n    # reuses Web's official webserver instead of opening a second one. Hosts\n    # without an enabled account service row leave this listener disabled.\n    - id: dsh-tui-webserver\n      name: '@deepseek-ai/dsh-host-webserver'\n      disabled: !!js >-\n        (() => {\n          const require = process.getBuiltinModule('node:module').createRequire(ctx.baseUrl)\n          try { require.resolve('@deepseek-ai/dsh-host-webserver/package.json') } catch { return true }\n          const entries = [...ctx.loader.entries()]\n          return !entries.some(entry => entry.options.name === '@deepseek-ai/dsh-deepseek-account-platform' && !entry.disabled)\n            || entries.some(entry => entry.options.id === 'webserver' && entry.options.name === '@deepseek-ai/dsh-host-webserver' && !entry.disabled)\n        })()\n      config:\n        host: 127.0.0.1\n        port: 0\n\n    # Built-in subscription OAuth sign-in: mounts available pi-ai routes\n    # (ChatGPT/Codex, Claude, Grok; newer pi-ai adds OpenAI direct and Meta)\n    # plus the /auth command. Its facade also delegates DeepSeek sign-in to\n    # the Host-owned account service when available. The TUI's /provider\n    # wizard gains its OAuth branch from ctx.dshAuth. Entry-level inject only —\n    # the internal module's own inject is empty so a stale patch cannot\n    # deadlock a composition lacking these services (#183 pattern).\n    - id: dsh-tui-auth\n      name: '@deepseek-harness-tui/dsh-tui/oauth'\n      inject: [llm, commands]\n\n    # The interactive front door. The plugin creates/resumes its agent at\n    # runtime, seeds the startup status line, and disposes the whole app tree\n    # (exiting the process) when the TUI unmounts. `dsh-tui --resume`\n    # feeds the session id through DSH_TUI_RESUME_SESSION (see\n    # src/sessionHistory.ts for the launcher contract).\n    - id: dsh-tui\n      name: '@deepseek-harness-tui/dsh-tui'\n      # The entry-level dependency augments the plugin's `agents` inject and\n      # prevents startup Session creation from racing WorkspaceRegistry init.\n      inject: [workspaceRegistry, agents, tuiWorkspaces, tuiScenes, tuiPanels, tuiDialogs, tuiStatus, tuiShortcuts, tuiRenderers, tuiThemes]\n      # `tuiWorkspaces`/`tuiScenes` (and the dsh-tui-extensions services,\n      # including `tuiThemes`)\n      # live in the entry-level inject ONLY as an ordering (and reload-rebind)\n      # guarantee alongside their service rows\n      # above — they are deliberately absent from the plugin's code-level\n      # inject (issue #183): the dsh CLI may read this patch from an older\n      # copy of the package than the plugin module it loads, and a hard\n      # code-level inject then deadlocks the tree at boot (\"pending (waiting\n      # for service: tuiWorkspaces)\"). Without the rows the TUI degrades:\n      # /workspace falls back to the local-only runtime, plugin scenes never\n      # open. (The comment sits below the inject line:\n      # verify-workspace-attachment.mjs asserts the name→inject distance.)\n      config:\n        # `provider` + `model` are the deployment DEFAULT route (used until a\n        # `/model` pick is persisted in ~/.dsh-tui/model.json, which then wins\n        # whole); a half-pinned pair is ignored outright (issue #67).\n        provider: deepseek-official\n        # Alt-screen fullscreen 布局：应用内鼠标选区（选择即复制, OSC 52 +\n        # wl-copy/xclip/xsel 兜底）、滚轮滚动、双击选词/三击选行。出厂默认开启，\n        # 与 schema 默认（index.ts fullscreen default true）保持一致——两处必须\n        # 同步翻转，否则本覆盖层会盖住 schema 默认，更新后用户仍落在 inline。\n        # 想退回 inline 主屏（终端原生滚动/选择）：/settings 全屏开关或 cordis.yml\n        # `fullscreen: false`——显式选择始终优先于默认。\n        fullscreen: true\n        # 以下为 /settings 可改的显示设置；每项说明与默认值见应用内 /settings 屏。\n        terminalImages: true\n        # diffLayout: auto\n        # mermaidDiagrams: true\n        # 通知（任务完成、等待授权、等待回答与计划评审）：off / unfocused（默认）/ always；方式：auto（默认）/ osc9 / bel / windows。\n        # taskNotifications: unfocused\n        # notificationMethod: auto\n        # windows 档：Windows 主机原生 toast（首次注册当前用户的 HKCU 标识，约延迟 3 秒）。\n        # auto 在 Windows 本地会话用此档，SSH 改走客户端终端；DSH 会话遇到已启用、正在运行的 cc-dsh-notifier 时，完成、审批与提问让位，计划评审不让位。\n        # jumpBack: false（默认关）；开启后窗格标题末尾追加 [dsh-tui:<16 hex>] 标记，完成、等待授权、等待回答与计划评审通知都可点击跳回，第一条能承诺跳回的 toast 注册 HKCU 协议键。\n        # 回复中 LaTeX 公式的显示方式：auto（默认，目前为 Unicode）/ image（支持图形的终端里块级公式显示为图片）/ unicode / source（保留源码）。/settings 可实时改。\n        # mathRendering: auto\n        # 每个请求实际生效的推理强度，按当前路由的 adapter 档位校验\n        #（deepseek: off/low/high/max）；非法值回落 adapter 默认。\n        # 这是部署默认值：上一次 /effort 的持久化选择（~/.dsh-tui/effort.json）\n        # 优先于它，它只决定\"还没有选择过\"的会话。\n        effort: max\n        # Shift+Tab session-mode cycle (array order IS the cycle order;\n        # absent → the built-in default/plan/full trio below). Each entry\n        # may declare any subset of the plan (on/off), sandbox (read-only/\n        # workspace-write/danger-full-access), and approval (ask/never)\n        # atoms; undeclared atoms are untouched. Entry index 0 is the\n        # unmarked base mode.\n        # modes:\n        #   - id: default\n        #     plan: false\n        #     sandbox: workspace-write\n        #     approval: ask\n        #   - id: plan\n        #     plan: true\n        #     sandbox: read-only\n        #     approval: ask\n        #   - id: full\n        #     plan: false\n        #     sandbox: danger-full-access\n        #     approval: never\n        # Deployment default for the Agent preset: the persisted `/preset`\n        # preference (~/.dsh-tui/agent-preset.json) outranks it, and\n        # DSH_TUI_PRESET (this run's explicit instruction) outranks both; the\n        # roster default (standard) closes the chain.\n        preset: !!js process.env.DSH_TUI_PRESET ?? undefined\n        workspace: !!js process.env.DSH_TUI_WORKSPACE_TARGET ?? undefined\n        sessionId: !!js process.env.DSH_TUI_RESUME_SESSION ?? undefined\n        # Agent backend (`dsh-tui --backend claude` → DSH_TUI_BACKEND); unset → /kernel's remembered pick, else dsh.\n        backend: !!js process.env.DSH_TUI_BACKEND || undefined\n\n    # Live working-line data source (thinking copy / running tool / turn\n    # summary). Mounted through @deepseek-harness-tui/dsh-tui's own\n    # `./working-activity` re-export, NOT the bare `dsh-working-activity`\n    # name: the dsh Loader resolves row names from the profile directory,\n    # and pnpm's isolated node_modules layout never links a transitive\n    # dependency into the profile root (npm's flat layout hid this), so the\n    # bare name died with ERR_MODULE_NOT_FOUND and disposed the whole app at\n    # boot (#60).\n    # The plugin stays mounted for its narration/system-prompt features and\n    # publishes the `workingActivity` session projection, which is where the\n    # TUI's working line comes from; never persist activity/status, so the\n    # shared log remains Web-readable.\n    - id: working-activity\n      name: '@deepseek-harness-tui/dsh-tui/working-activity'\n      config:\n        publish: false\n        publishIntervalMs: 500\n"
    },
    {
      "path": "src/dsh-adapter/index.ts",
      "content": "/**\n * dsh-tui plugin entry. The TUI implementation lives in `./plugin.tsx` (its\n * render path is JSX); this module owns the plugin surface (`name`/`inject`/\n * `Config`/`apply`) at the package entry module and delegates\n * `apply` through a dynamic import so entry-scanning tooling and the Loader\n * resolve a plain `.ts` module.\n * @module @deepseek-harness-tui/dsh-tui\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport Schema from '@deepseek-ai/schemastery'\nimport type { SessionModeSpec } from '../sessionModes.js'\nimport type { NotificationMethod, TaskNotifications } from '../ink/terminal-notification.js'\nimport { parseBackendChoice } from './backend-registry.js'\nimport { parseBackendId, type KernelBackendId } from '../kernelPrefs.js'\nimport { ALL_SIDE_PANELS, BTW_CONTEXT_BUDGET_DEFAULT, BTW_CONTEXT_TURNS_DEFAULT, DEFAULT_COMPANION_SKIN, DEFAULT_STATUS_BAR, normalizeBtwContextBudget, normalizeBtwContextTurns, normalizeCompanionSkin, normalizePageMargin, normalizeSidePanelPanels, normalizeSidePanelRatio, type CodeFrameStyle, type ImageBacking, type MathImageBacking, type MathImageScale, type MathRendering, type PageMarginSetting, type ScrollGutterMode, type StatusBarConfig, type ToolBackground } from '../tuiDisplayPrefs.js'\nimport { SHORTCUT_ACTIONS, type ShortcutActionId } from '../utils/keymap.js'\nimport { normalizeSplashFont, type SplashFontSetting } from '../components/splashFonts.js'\nimport { normalizeBrandSetting, type BrandSetting } from '../branding.js'\nimport { editableConfig, type RuntimeConfig } from './compat/settings.js'\nimport { EDITABLE_CONFIG_KEYS } from '../settings/definitions.js'\nimport { peekEntrySlot, takeEntryAttach } from './entry-slot.js'\n\nexport const name = 'dsh-tui'\n// `tuiWorkspaces` must stay OUT of this code-level inject (issue #183): the\n// dsh CLI resolves the bundle's cordis.patch.yml from the FIRST copy of this\n// package found from its own install anchor (typically the global launcher),\n// while the Loader imports the plugin module from the profile's copy. When\n// the two copies skew, the patch may predate the dsh-tui-workspaces row — a\n// hard inject here then deadlocks the whole tree at boot (\"pending (waiting\n// for service: tuiWorkspaces)\"). The bundle patch keeps tuiWorkspaces in the\n// row-level inject purely as an ordering guarantee when the row exists; when\n// it does not, plugin.ts/channel.ts fall back to a local workspace runtime.\nexport const inject = ['agents']\n\n/**\n * dsh-tui plugin configuration: session attachment, model route, working\n * directory, and display preferences.\n */\nexport interface Config {\n  /** Existing session to attach; a fresh session is created when absent. */\n  sessionId?: string\n  /** Agent backend the session runs on: `dsh` (default), the DeepSeek\n   *  Harness agent; `claude`, the experimental Claude Agent backend driving\n   *  the local Claude CLI through the Claude Agent SDK (optional peer\n   *  `@anthropic-ai/claude-agent-sdk`); `codex`, the experimental Codex\n   *  backend driving the user's own `codex` CLI over `codex app-server`.\n   *  `dsh-tui --backend <id>` sets it through `DSH_TUI_BACKEND`.\n   *\n   *  A plain `string` on purpose: this is the **input** surface, so an embedder\n   *  writing `{ backend: 'codex' }` keeps compiling. The schema normalizes syntax;\n   *  the boot checks registry membership after assembling installed bundles.\n   *  The `BackendId` brand stays inside the package, where it guards session\n   *  refs and `~/.dsh-tui/backends/<id>/` paths. Declaring the\n   *  branded `KernelBackendId` here breaks published consumers instead\n   *  (PR #1380 review R1). */\n  backend?: string\n  /** LLM provider route. The route resolves atomically (issue #67): the\n   *  `/model` choice persisted in `~/.dsh-tui/model.json` — the route the\n   *  last session ran — wins whole; otherwise a `provider`+`model` pair named\n   *  here is the deployment DEFAULT; otherwise `agentDefaultModel` supplies\n   *  the provider-neutral Harness default. A bare embedder without that\n   *  service falls back to DeepSeek. A half-pinned pair (only one of the two\n   *  keys) is ignored outright and never half-overrides the persisted\n   *  choice. */\n  provider?: string\n  /** Model override passed to the agent; resolved together with `provider`\n   *  as one atomic route (see `provider`). */\n  model?: string\n  /** Session working directory. When absent, the git worktree root\n   *  containing the invoking directory wins (the invoking directory itself\n   *  outside any worktree) — never a bare launch subdirectory (issue #96). */\n  cwd?: string\n  /** Absolute local path, file URL, or provider URI resolved before the\n   *  initial agent is created. */\n  workspace?: string\n  /** Reasoning effort applied to every request, validated against the live\n   *  route's adapter levels (an unlisted level is ignored and the adapter\n   *  default applies). This is the deployment DEFAULT beneath the persisted\n   *  `/effort` choice (the level the last session ran); it also seeds the\n   *  startup status line until the first request header reports the live\n   *  value. */\n  effort?: string\n  /** Settings user-layer default for future sessions; when set it outranks\n   *  both the persisted `/effort` choice and the `effort` fallback. */\n  effortDefault?: string\n  /** Show the header whale and its idle animation. */\n  whale?: boolean\n  whaleIdle?: boolean\n  /** Big-text face on the header splash (settings `dsh-tui.splashFont`):\n   *  `daily` (the default) rotates by local date, any other value is a font\n   *  id from `components/splashFonts.ts` (`bold`/`square`/…) pinning that one\n   *  face. An unknown value falls back to `daily`. */\n  splashFont?: SplashFontSetting\n  /** Brand look of the splash and theme (settings `dsh-tui.brand`): `auto`\n   *  (the default) follows the active backend — Claude boots orange;\n   *  `deepseek`/`claude` pin one look. Junk normalizes to `auto`. */\n  brand?: BrandSetting\n  /** Swap the header's pixel whale for the static maid portrait. */\n  whaleGirl?: boolean\n  /** Reduce decorative header content and colors. */\n  minimal?: boolean\n  /** Show the live working line derived in-process from base session events. */\n  activity?: boolean\n  /** Working-activity indicator preset (`moon8`/`moon`/`comet`/`dots`/…\n   *  or `random`; see activityFrames.ts). When absent, the `/activity`\n   *  choice persisted in `~/.dsh-tui/working-activity.json` wins, then the\n   *  `moon8` default. */\n  activityFrames?: string\n  /** Show the segmented context bar (the band under the input with the\n   *  `ctx used/window` readout) in the status footer; off hides that row\n   *  while the status/mode lines stay (issue #29). */\n  contextBar?: boolean\n  /** Run in the terminal's alternate screen (full-screen terminal layout).\n   *  Defaults to true — the fullscreen surface is the more complete one\n   *  (mouse, timeline rail, scrollbar gutter, selection copy), so fresh\n   *  installs start there; cordis.yml `fullscreen: false` or a /settings\n   *  toggle opts back into the inline main-screen layout. */\n  fullscreen?: boolean\n  /** Allow terminal image previews when supported (default true). Saved\n   *  /settings choices override this value after restart. The environment\n   *  override DSH_TUI_DISABLE_TERMINAL_IMAGES can always force previews off. */\n  terminalImages?: boolean\n  /** Launchpad landing page (settings `dsh-tui.launchpad`): an ordinary\n   *  launch (no --resume, no first prompt) starts on the launchpad — the\n   *  page where the first sentence gets typed. On by default; `false` boots\n   *  straight into the chat page. Saved /settings choices override this\n   *  value after restart; DSH_TUI_NO_LAUNCHPAD=1 skips it regardless. */\n  launchpad?: boolean\n  /** UI language: `en` / `zh`. When absent, the `DSH_TUI_LANG` env var wins,\n   *  then the `/lang` choice persisted in `~/.dsh-tui/lang.json`, then `zh`. */\n  lang?: string\n  /** Agent preset id new sessions compose from (standard/ptc/minimal/\n   *  cordis/… when the roster is mounted). A `DSH_TUI_PRESET` launch\n   *  instruction outranks everything; otherwise the `/preset` choice\n   *  persisted in `~/.dsh-tui/agent-preset.json` wins, then this value as\n   *  the deployment default, then the roster default (`standard`). */\n  preset?: string\n  /** Edit/Write diff presentation: `auto` picks side-by-side on wide\n   *  terminals (≥110 cols) and unified below; `split`/`unified` force one\n   *  layout. Editable live from the `/settings` screen. */\n  diffLayout?: 'auto' | 'split' | 'unified'\n  /** Thinking-block display: `preview` (default) streams a 2-3 line live\n   *  preview and folds each step when it settles; `full` keeps thinking\n   *  expanded until the whole turn ends. Editable live from `/settings`. */\n  thinkingFold?: 'preview' | 'full'\n  /** Grouping/folding of consecutive background-job cards: `auto` (default)\n   *  groups any run of ≥2 adjacent job cards and folds a run of 3+ into its\n   *  summary line once every member settled; `always` folds any run of 2+\n   *  immediately; `never` never folds on its own (a click on the group\n   *  header still folds one run). Editable live from `/settings`. */\n  jobGroupFold?: 'auto' | 'always' | 'never'\n  /** Tool-card background strength; defaults to no added background. */\n  toolBackground?: ToolBackground\n  /** What the fullscreen transcript's right gutter shows (settings\n   *  `dsh-tui.scrollGutter`): `timeline` turn rail (default), `scrollbar`\n   *  proportional thumb, or `hidden`. */\n  scrollGutter?: ScrollGutterMode\n  /** Root page inset (settings `dsh-tui.pageMargin`): a preset name\n   *  (`none` / `slim` / `normal` (default) / `roomy`) or a custom `NxM`\n   *  spec (columns per side × rows top/bottom) that insets the whole UI\n   *  from the terminal edges. Terminals without their own viewport padding\n   *  (bare WSL, tmux, SSH) otherwise hug the screen border. */\n  pageMargin?: PageMarginSetting\n  /** Terminal-card header folding (settings `dsh-tui.foldTerminalCommand`):\n   *  `true` collapses a multi-line command title to its first line plus a\n   *  `+N lines` hint; Ctrl+O / clicking the card expands it. Default off —\n   *  the full title keeps rendering. */\n  foldTerminalCommand?: boolean\n  /** Turn-usage ledger row (settings `dsh-tui.turnUsageRow`): the quiet\n   *  right-aligned line that closes each turn in the transcript (tokens\n   *  in/out, cache split, span, retries). Off by default; the ledger data\n   *  feeds /tokens, /status and the footer hover regardless. */\n  turnUsageRow?: boolean\n  /** Show the session name as a chip on the prompt top border's right side\n   *  (settings `dsh-tui.promptSessionLabel`); off by default. */\n  promptSessionLabel?: boolean\n  /** Fullscreen draft editor (settings `dsh-tui.expandEditor`): the ⛶\n   *  affordance in the input row and the expandEditor shortcut (default\n   *  Ctrl+Shift+E) expand the draft into a whole-screen editor. On by\n   *  default; off removes both entry points. */\n  expandEditor?: boolean\n  /** Smooth streaming reveal (settings `dsh-tui.smoothStreaming`): live\n   *  assistant text, expanded thinking, and tool call bodies paint through\n   *  a ~30fps reveal instead of jumping per provider burst — bursty or\n   *  one-shot deliveries read as an even flow. On by default. */\n  smoothStreaming?: boolean\n  /** System notifications for successful task completions, waiting\n   *  approvals, waiting questions and waiting plan reviews: off, unfocused\n   *  (default), or always. */\n  taskNotifications?: TaskNotifications\n  /** Notification transport: auto (default), OSC 9, BEL, or the native Windows\n   *  toast, which off Windows resolves back to the probed terminal protocol. */\n  notificationMethod?: NotificationMethod\n  /** Jump back from notification toasts (settings `dsh-tui.jumpBack`): on\n   *  Windows the pane title gains a ` [dsh-tui:<16 hex>]` suffix so a toast can\n   *  reopen this exact pane; enabling also registers a per-user HKCU protocol\n   *  key on the first toast. Off by default — the title stays untouched and\n   *  nothing is registered. */\n  jumpBack?: boolean\n  /** Mermaid diagrams (settings `dsh-tui.mermaidDiagrams`): ```mermaid\n   *  fences in replies render as Unicode box-drawing art — flowcharts,\n   *  sequence/state/class/ER diagrams, pie, mindmap, timeline, gitGraph —\n   *  laid out in-process, no browser or image protocol. A diagram wider\n   *  than the viewport or of an unsupported type keeps the fenced source.\n   *  On by default; off always shows the source. */\n  mermaidDiagrams?: boolean\n  /** Code-frame shape (settings `dsh-tui.codeFrameStyle`): `light`\n   *  (default) is the open rail frame — corner + language label on top,\n   *  a left rail with one padding column per row, no right wall or\n   *  bottom edge; `full` closes the box with a right wall (continuous\n   *  across wrapped rows) and a bottom edge. The narrow fallback (net\n   *  body width < 8) always stays the plain ANSI fence. */\n  codeFrameStyle?: CodeFrameStyle\n  /** LaTeX math (settings `dsh-tui.mathRendering`): `$…$` / `\\(…\\)` inline\n   *  and `$$…$$` / `\\[…\\]` blocks in replies. `auto` (default) uses the best\n   *  available renderer — today Unicode text: Greek and operator symbols,\n   *  scripts, fractions and operator limits stacked in display blocks,\n   *  matrices, cases; `unicode` pins it; `source` always shows the TeX.\n   *  Unsupported, still-streaming, or too-wide formulas keep their source. */\n  mathRendering?: MathRendering\n  /** Display-formula image size (settings `dsh-tui.mathImageScale`), used\n   *  with `mathRendering: image`: `auto` matches the body text, `large` and\n   *  `xlarge` set display math bigger — which also hands the terminal more\n   *  device pixels per stroke, the only sharpness lever a terminal image has.\n   *  Inline formulas keep the base scale. */\n  mathImageScale?: MathImageScale\n  /** Formula-image backing (settings `dsh-tui.mathImageBacking`): `transparent`\n   *  paints only the formula and lets the terminal background show through;\n   *  `terminal` composites it onto the terminal's background colour. */\n  mathImageBacking?: MathImageBacking\n  /** Transcript-image backing (settings `dsh-tui.imageBacking`): `transparent`\n   *  floats photos and illustrations on whatever the terminal shows;\n   *  `terminal` composites them onto the terminal's background colour. */\n  imageBacking?: ImageBacking\n  /** @deprecated Use `mathRendering`; `false` still means `source`. */\n  latexMath?: boolean\n  /** Auto recap on open (settings `dsh-tui.recapOnOpen`): opening or resuming a\n   *  session summarizes its recent activity into a dim line at the bottom of\n   *  the transcript. On by default; off leaves `/recap` as the manual path. */\n  recapOnOpen?: boolean\n  /** Status-footer field visibility and compact presentation preferences. */\n  statusBar?: Partial<StatusBarConfig>\n  /** Side panel (settings `dsh-tui.sidePanel.*`): the two-column layout's\n   *  master switch, its startup state, the chat-column fraction, and the\n   *  enabled panels in PanelBar order. Every member is normalized at parse\n   *  time, so a hand-edited value can never wedge the layout. */\n  sidePanel?: {\n    /** Master switch of the split layout; on by default. Off makes /panel\n     *  and Ctrl+B fall back to the fullscreen panels. */\n    splitEnabled?: boolean\n    /** Whether a session opens with the sidebar expanded (off by default, so\n     *  the upgrade leaves the layout alone); Ctrl+B toggles it live. */\n    open?: boolean\n    /** Chat column as a fraction of the content width, clamped to 0.1–0.95\n     *  (default 0.68); +/- while the panel is focused nudges it live. */\n    ratio?: number\n    /** Which panels the side-panel bar shows, in PanelBar order. `*` (the\n     *  default) means every registered panel — built-ins plus whatever a\n     *  plugin registers later; an explicit comma list means exactly those ids\n     *  (an unknown-but-well-formed id stays as a placeholder for a plugin).\n     *  Registration never rewrites this value: a malformed id is dropped, the\n     *  rest keep their order. */\n    panels?: string\n  }\n  /** Companion pet (settings `dsh-tui.companion.*`): which skin the panel\n   *  pet wears. */\n  companion?: {\n    /** 'deepy' (default, the deepy whale kit) or 'whale' (the splash's\n     *  layered pixel whale). Unknown ids normalize to deepy. */\n    skin?: string\n  }\n  /** btw thread context (settings `dsh-tui.btw.*`): how much of the side\n   *  thread follows into the next ask. Members normalize (turns clamp\n   *  1-8, budget clamps 1k-200k), so junk cannot wedge the thread. */\n  btw?: {\n    /** Completed Q/A pairs carried into a follow-up ask, 1-8 (default 4). */\n    contextTurns?: number\n    /** Total character budget of that carried context (default 24000;\n     *  the per-answer cap derives internally as min(8k, budget/2)). */\n    contextBudget?: number\n  }\n  /** Built-in action-shortcut overrides (`paste: 'alt+v'`), keyed by action\n   *  id (see the keymap utility). Combos are `ctrl+`/`alt+`/`shift+` plus a\n   *  key; several combos may be comma-separated. Unset actions keep their\n   *  defaults; the `/settings` screen edits the same keys live (its user\n   *  layer wins over this file). */\n  shortcuts?: Partial<Record<ShortcutActionId, string>>\n  /** Shift+Tab session-mode cycle (array order IS the cycle order; index 0\n   *  is the unmarked base mode). Each entry bundles any subset of the\n   *  `plan`/`sandbox`/`approval` atoms; absent → the built-in\n   *  default/plan/full cycle (see sessionModes.ts). */\n  modes?: SessionModeSpec[]\n  /** Upstream auto-retry for DSH sessions (default on): seed a retry\n   *  policy (5 attempts, transport-drop-aware failure codes) on the\n   *  llm-pi-ai provider route the bound session actually uses whenever\n   *  it declares no retryPolicy, through the llm-pi-ai settings section\n   *  — the policy the kernel's llm-retry plugin executes. Dormant\n   *  channels are never written; routes with an explicit retryPolicy are\n   *  never overwritten; setting this to false opts out entirely. */\n  upstreamRetry?: boolean\n}\n\n/** The complete two-stage parse: syntax, then registry membership (P0 D1).\n *  Empty, malformed or unregistered values mean \"not configured\". Unlike the\n *  syntax-only Config schema, this helper requires discovery to have run. */\nexport function normalizeBackendChoice(value: unknown): KernelBackendId | undefined {\n  return parseBackendChoice(value)\n}\n\nexport const Config: Schema<Config, RuntimeConfig<Config>> = editableConfig<Config>(Schema.object({\n  sessionId: Schema.string().required(false),\n  // A transform, not a union: the row reads `DSH_TUI_BACKEND`, and a stray\n  // export (`Claude`, a typo) must not fail the whole boot — case and blanks\n  // are normalized here and the id-shape gate drops junk. Cordis validates\n  // before `apply` assembles installed backends: membership must wait until\n  // after that discovery, or a third-party Config choice is erased.\n  backend: Schema.transform(Schema.string(), value => parseBackendId(value)),\n  // No schema defaults on the route: a `.default()` here would make an\n  // unset key indistinguishable from an explicit cordis.yml choice and the\n  // persisted `/model` preference could never win (issue #30). The defaults\n  // live at the end of the fallback chain in modelRoute.ts instead.\n  provider: Schema.string().required(false),\n  model: Schema.string().required(false),\n  cwd: Schema.string().required(false),\n  workspace: Schema.string().required(false),\n  effort: Schema.string().required(false),\n  effortDefault: Schema.string().required(false),\n  whale: Schema.boolean().default(true),\n  whaleIdle: Schema.boolean().default(true),\n  // The face registry grows with new releases, so this is a transform rather\n  // than a union: any string parses and junk lands on `daily` at parse time\n  // (a union would fail the whole boot on a stale id). The `/settings` field\n  // offers exactly the registry's ids. The default is deliberately NOT a\n  // `.default()` here — the volatile wrapper swallows it (same shape as\n  // pageMargin, whose unset value also reads `undefined`), so `daily` comes\n  // from `normalizeSplashFont` at every read site.\n  splashFont: Schema.transform(\n    Schema.string(),\n    value => normalizeSplashFont(value),\n  ),\n  // 同 splashFont 的 transform 而非 union：cordis.yml 保持决定权，`auto`\n  // 的默认值由 `normalizeBrandSetting` 在每个读取点给出。\n  brand: Schema.transform(\n    Schema.string(),\n    value => normalizeBrandSetting(value),\n  ),\n  whaleGirl: Schema.boolean().default(false),\n  minimal: Schema.boolean().default(false),\n  activity: Schema.boolean().default(true),\n  activityFrames: Schema.string().required(false),\n  contextBar: Schema.boolean().default(true),\n  fullscreen: Schema.boolean().default(true),\n  terminalImages: Schema.boolean().default(true),\n  // No `.default()` on purpose (same rule as recapOnOpen): an unset key must\n  // stay distinguishable from an explicit `false`, and the boot reads\n  // undefined as on (`config.launchpad !== false`).\n  launchpad: Schema.boolean(),\n  lang: Schema.string().required(false),\n  preset: Schema.string().required(false),\n  diffLayout: Schema.union(['auto', 'split', 'unified']).default('auto'),\n  thinkingFold: Schema.union(['preview', 'full']).default('preview'),\n  jobGroupFold: Schema.union(['auto', 'always', 'never']).default('auto'),\n  toolBackground: Schema.union(['none', 'subtle', 'strong']).default('none'),\n  scrollGutter: Schema.union(['timeline', 'scrollbar', 'hidden']).default('timeline'),\n  // Preset names AND custom `NxM` specs must survive validation (a custom\n  // spec is not a fixed union member); junk is normalized to `normal` by\n  // the transform, so every parsed config carries a valid setting.\n  pageMargin: Schema.transform(\n    Schema.string().default('normal'),\n    value => normalizePageMargin(value),\n  ),\n  foldTerminalCommand: Schema.boolean().default(false),\n  turnUsageRow: Schema.boolean().default(false),\n  promptSessionLabel: Schema.boolean().default(false),\n  expandEditor: Schema.boolean().default(true),\n  smoothStreaming: Schema.boolean().default(true),\n  taskNotifications: Schema.union(['off', 'unfocused', 'always']),\n  notificationMethod: Schema.union(['auto', 'osc9', 'bel', 'windows']),\n  // No `.default()` on purpose (same rule as recapOnOpen): an unset key must\n  // stay distinguishable from an explicit `false` so cordis.yml keeps the\n  // deciding vote; the setting parser resolves `value.jumpBack ??\n  // config.jumpBack ?? false` at the read site.\n  jumpBack: Schema.boolean(),\n  mermaidDiagrams: Schema.boolean().default(true),\n  codeFrameStyle: Schema.union(['light', 'full']),\n  mathRendering: Schema.union(['auto', 'image', 'unicode', 'source']),\n  mathImageScale: Schema.union(['auto', 'large', 'xlarge']),\n  mathImageBacking: Schema.union(['transparent', 'terminal']),\n  imageBacking: Schema.union(['transparent', 'terminal']),\n  latexMath: Schema.boolean(),\n  // No `.default()` on purpose (the volatile wrapper swallows it; same rule as\n  // splashFont): an unset key must stay distinguishable from an explicit\n  // `false`, and the read site already treats undefined as on\n  // (`describe().value.recapOnOpen !== false`, see channel.ts).\n  recapOnOpen: Schema.boolean(),\n  statusBar: Schema.object({\n    compact: Schema.boolean().default(DEFAULT_STATUS_BAR.compact),\n    model: Schema.boolean().default(DEFAULT_STATUS_BAR.model),\n    thinking: Schema.boolean().default(DEFAULT_STATUS_BAR.thinking),\n    cwd: Schema.boolean().default(DEFAULT_STATUS_BAR.cwd),\n    contextUsage: Schema.boolean().default(DEFAULT_STATUS_BAR.contextUsage),\n    cache: Schema.boolean().default(DEFAULT_STATUS_BAR.cache),\n    tokens: Schema.boolean().default(DEFAULT_STATUS_BAR.tokens),\n    // Session cost estimate (≈¥) beside the token totals; StatusLine gates the\n    // chip on it. The slot must be declared here: schemastery drops an\n    // undeclared key on the way back in, so the /settings row would read\n    // \"(unset)\" and every edit would silently revert.\n    cost: Schema.boolean().default(DEFAULT_STATUS_BAR.cost),\n    tps: Schema.boolean().default(DEFAULT_STATUS_BAR.tps),\n    gitBranch: Schema.boolean().default(DEFAULT_STATUS_BAR.gitBranch),\n    sessionTitle: Schema.boolean().default(DEFAULT_STATUS_BAR.sessionTitle),\n    sessionId: Schema.boolean().default(DEFAULT_STATUS_BAR.sessionId),\n    goal: Schema.boolean().default(DEFAULT_STATUS_BAR.goal),\n    mode: Schema.boolean().default(DEFAULT_STATUS_BAR.mode),\n    contextBar: Schema.boolean().default(DEFAULT_STATUS_BAR.contextBar),\n    activity: Schema.boolean().default(DEFAULT_STATUS_BAR.activity),\n    trajectory: Schema.boolean().default(DEFAULT_STATUS_BAR.trajectory),\n    shortcutHint: Schema.boolean().default(DEFAULT_STATUS_BAR.shortcutHint),\n    pluginFields: Schema.boolean().default(DEFAULT_STATUS_BAR.pluginFields),\n    pluginFieldsOrder: Schema.string().default(DEFAULT_STATUS_BAR.pluginFieldsOrder),\n  }).default({ ...DEFAULT_STATUS_BAR }),\n  // Side-panel preferences, same shape as statusBar: every member carries a\n  // default so an unset cordis.yml block and a partially hand-written one\n  // both resolve, and the transforms keep junk (a string ratio, an id with\n  // illegal characters) out of the live stores.\n  sidePanel: Schema.object({\n    splitEnabled: Schema.boolean().default(true),\n    open: Schema.boolean().default(false),\n    ratio: Schema.transform(\n      Schema.number().default(0.68),\n      value => normalizeSidePanelRatio(value),\n    ),\n    panels: Schema.transform(\n      Schema.string().default(ALL_SIDE_PANELS),\n      value => normalizeSidePanelPanels(value),\n    ),\n  }).default({ splitEnabled: true, open: false, ratio: 0.68, panels: ALL_SIDE_PANELS }),\n  companion: Schema.object({\n    skin: Schema.transform(\n      Schema.string().default(DEFAULT_COMPANION_SKIN),\n      value => normalizeCompanionSkin(value),\n    ),\n  }).default({ skin: DEFAULT_COMPANION_SKIN }),\n  // btw thread context: schema defaults + transforms (same shape as\n  // sidePanel above) so an unset cordis.yml block and junk values both\n  // resolve to the documented 4 turns / 24k chars before the stores see\n  // them (the store normalize remains the second, identical gate).\n  btw: Schema.object({\n    contextTurns: Schema.transform(\n      Schema.number().default(BTW_CONTEXT_TURNS_DEFAULT),\n      value => normalizeBtwContextTurns(value),\n    ),\n    contextBudget: Schema.transform(\n      Schema.number().default(BTW_CONTEXT_BUDGET_DEFAULT),\n      value => normalizeBtwContextBudget(value),\n    ),\n  }).default({ contextTurns: BTW_CONTEXT_TURNS_DEFAULT, contextBudget: BTW_CONTEXT_BUDGET_DEFAULT }),\n  // One optional combo string per customizable action (no defaults: unset\n  // keeps the built-in binding; see Config.shortcuts).\n  shortcuts: Schema.object(\n    Object.fromEntries(SHORTCUT_ACTIONS.map(action => [action.id, Schema.string().required(false)])),\n  ).required(false),\n  modes: Schema.array(\n    Schema.object({\n      id: Schema.string(),\n      label: Schema.string().required(false),\n      plan: Schema.boolean().required(false),\n      sandbox: Schema.union(['read-only', 'workspace-write', 'danger-full-access']).required(false),\n      approval: Schema.union(['ask', 'never']).required(false),\n      permission: Schema.string().required(false),\n    }),\n  ).required(false),\n  // Upstream auto-retry seeding (see upstream-retry.ts): on by default so\n  // an upstream link drop retries like any other transient failure.\n  upstreamRetry: Schema.boolean().default(true),\n}), EDITABLE_CONFIG_KEYS as readonly (keyof Config)[])\n\n/**\n * Start the interactive TUI front door, delegating to the JSX implementation\n * in `./plugin.tsx` (see its module doc for the full contract).\n * @param ctx - the plugin context.\n * @param config - the validated dsh-tui configuration.\n * @returns a promise settling when the Loader entry has scheduled its runtime.\n */\nexport async function apply(ctx: Context, config: RuntimeConfig<Config>): Promise<void> {\n  // The entry already mounted the screen in this process (./entry-slot.ts):\n  // the row only runs the DSH side and hands the session to that screen.\n  const entrySlot = peekEntrySlot()\n  if (entrySlot !== undefined) {\n    entrySlot.rowSeen = true\n    attachToEntry(ctx, config)\n    return\n  }\n  // Upstream drift is NO LONGER spammed to stderr here: per-package\n  // console.warn lines interleave with the TUI frame redraw and arrive\n  // garbled (typewriter animation repaints over them). The merged,\n  // natural-language notice now renders in the logo header under the\n  // startup tip (LogoV2 ← upstreamDriftSummary); CI keeps the hard gate\n  // via scripts/verify-upstream-contract.ts.\n  const { apply: tuiApply, handleStartupError } = await import('./plugin.js')\n  let disposed = false\n  ctx.effect(() => () => { disposed = true })\n  // Registry diagnostics can await the whole Loader. Do not make this Host\n  // row await the runtime in return. Let Host providers settle before starting\n  // a Cordis-owned child; the original row still owns volatile Config.\n  const loader = ctx.get('loader') as { await(): Promise<unknown> } | undefined\n  void (loader?.await() ?? ctx.fiber.await()).then(() => {\n    if (disposed) return\n    return ctx.plugin({\n      name: 'dsh-tui-runtime',\n      apply: (runtimeCtx: Context) => tuiApply(runtimeCtx, config, ctx),\n    })\n  }).catch(error => {\n    if (!disposed) handleStartupError(ctx, error)\n  })\n}\n\n/** The row under the entry's screen: the DSH side in its own runtime fiber\n *  once the Loader settled, never a second render; a recompose stays idle. */\nfunction attachToEntry(ctx: Context, config: RuntimeConfig<Config>): void {\n  let disposed = false\n  ctx.effect(() => () => { disposed = true })\n  const loader = ctx.get('loader') as { await(): Promise<unknown> } | undefined\n  void (loader?.await() ?? ctx.fiber.await()).then(() => {\n    if (disposed) return\n    // Taken only now: a row that unloads before the Loader settled leaves the\n    // first attach to the next row. A later row takes over only once the\n    // previous one unloaded (#1651).\n    const attach = takeEntryAttach() ?? peekEntrySlot()?.reattachDsh?.()\n    if (attach === undefined) {\n      ctx.logger.warn('dsh-tui: the entry\\'s screen already holds a DSH session; this dsh-tui row stays idle')\n      return\n    }\n    return ctx.plugin({\n      name: 'dsh-tui-runtime',\n      apply: (runtimeCtx: Context) => attach(runtimeCtx, config, ctx),\n    })\n  }).catch((error: unknown) => {\n    ctx.logger.error(`dsh-tui: the DSH side failed to start under the entry's screen: ${error instanceof Error ? error.message : String(error)}`)\n  })\n}\n\n// ── The Backend contribution family (B-2) ─────────────────────────────────────\n// `alpha`, and deliberately narrow: the *declaration* shape, its validator, the\n// admission verdict and the projection this package uses for its own manifests.\n// A third-party author writes a declaration by hand against exactly this surface\n// (scripts/verify-public-config-types.mjs compiles a real consumer file against\n// the published declarations), and from here on it may only grow — removing any\n// of it is a breaking change. What is NOT here: the registry, the loader and the\n// picker. Those stay the host's; an installed bundle's declaration reaches them\n// through the boot-time assembly (`backend-assembly.ts`, D-1) on top of the W-2\n// admission chain (see docs/plugins.md).\nexport {\n  BACKEND,\n  BACKEND_CAPABILITY_NAMES,\n  BACKEND_RESERVED_IDS,\n  validateBackendSpec,\n  type BackendInstallRecipe,\n  type BackendSpec,\n} from '../adapter/spec/tui-contributions.js'\nexport { backendAdmission, type BackendAdmission, type BackendAdmissionHost } from './backend-admission.js'\nexport { backendContributionOf } from './backend-contribution.js'\n"
    },
